-- =====================================================================
-- 面试题知识库 · 数据库设计 + Mock 数据（由真实开发库 DDL 同步生成）
-- 说明：
--   1) 本文档与 interview-backend 实体/查询完全对齐：user 以邮箱/手机号登录（无 username），
--      category 支持 sort_order 手动排序，article 含 doc_url 文档链接，另有 daily_quote 每日一句表。
--   2) 管理员：2090323327@qq.com / 123456；普通用户：2090323328@qq.com / 123456（BCrypt 已预生成）。
--   3) 直接执行本文件即可创建库、表和种子数据（可重复执行）。
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `interview` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `interview`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- =====================================================================
-- 建表（先删后建，便于重复执行）
-- =====================================================================

DROP TABLE IF EXISTS `admin_log`;
DROP TABLE IF EXISTS `article_tag`;
DROP TABLE IF EXISTS `tag`;
DROP TABLE IF EXISTS `article`;
DROP TABLE IF EXISTS `daily_quote`;
DROP TABLE IF EXISTS `user_upload`;
DROP TABLE IF EXISTS `user_notification`;
DROP TABLE IF EXISTS `access_apply`;
DROP TABLE IF EXISTS `category`;
DROP TABLE IF EXISTS `user`;

CREATE TABLE `user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `password_hash` varchar(100) NOT NULL COMMENT 'BCrypt 哈希',
  `rootpassword` varchar(50) NOT NULL DEFAULT '' COMMENT '原始密码（演示/联调用）',
  `nickname` varchar(50) NOT NULL DEFAULT '' COMMENT '昵称',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT '头像URL（OSS或静态资源），空=默认头像',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱（可空，唯一；未填写存 NULL 避免空串冲突）',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `role` varchar(20) NOT NULL DEFAULT 'USER' COMMENT 'USER/ADMIN',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1正常 0禁用',
  `full_access` tinyint NOT NULL DEFAULT '0' COMMENT '1=老用户默认全权限，新注册默认0',
  `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_email` (`email`),
  UNIQUE KEY `uk_phone` (`phone`),
  KEY `idx_status` (`status`),
  KEY `idx_role` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账号表（管理员/普通用户）';

CREATE TABLE `category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '分类名',
  `slug` varchar(80) NOT NULL COMMENT 'URL标识',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '0=顶级分类',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重，越小越靠前',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '分类描述',
  `access_level` varchar(10) NOT NULL DEFAULT 'PUBLIC' COMMENT 'PUBLIC=公开 APPLY=需申请',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分类表（多级）';

CREATE TABLE `daily_quote` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `content` varchar(500) NOT NULL COMMENT '语录内容',
  `author` varchar(100) NOT NULL DEFAULT '' COMMENT '作者/署名',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日一句';

CREATE TABLE `user_upload` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT '上传用户ID',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `category_name` varchar(100) NOT NULL DEFAULT '' COMMENT '主题分类（用户选择或自定义）',
  `group_name` varchar(100) NOT NULL DEFAULT '' COMMENT '分组（用户选择或自定义，可空）',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '原始md文件名',
  `content_md` longtext NOT NULL COMMENT 'Markdown 原文',
  `content_html` longtext NOT NULL COMMENT '渲染并消毒后的 HTML',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待处理 1已回复',
  `admin_reply` varchar(2000) NOT NULL DEFAULT '' COMMENT '管理员回复内容',
  `replied_at` datetime DEFAULT NULL COMMENT '回复时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户上传内容（普通用户提交，管理员回复）';

CREATE TABLE `user_notification` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `target_user_id` bigint unsigned DEFAULT NULL COMMENT '接收用户ID（普通用户通知）',
  `target_role` varchar(20) NOT NULL DEFAULT '' COMMENT '接收角色，ADMIN=发给所有管理员',
  `type` varchar(30) NOT NULL COMMENT 'UPLOAD_REPLY/NEW_UPLOAD',
  `content` varchar(500) NOT NULL DEFAULT '' COMMENT '通知内容',
  `upload_id` bigint unsigned DEFAULT NULL COMMENT '关联上传内容ID，点击跳转',
  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '0未读 1已读',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_target_user` (`target_user_id`,`is_read`),
  KEY `idx_target_role` (`target_role`,`is_read`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='站内通知（管理员回复通知上传者、新上传通知管理员）';

CREATE TABLE `access_apply` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT '申请人',
  `scope` varchar(10) NOT NULL DEFAULT 'CATEGORY' COMMENT 'CATEGORY=单分类 ALL=全部分类',
  `category_id` bigint unsigned DEFAULT NULL COMMENT 'scope=CATEGORY 时申请的分类ID',
  `reason` varchar(200) NOT NULL DEFAULT '' COMMENT '申请理由（选填）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待审批 1已通过 2已拒绝',
  `admin_reply` varchar(2000) NOT NULL DEFAULT '' COMMENT '管理员回复/意见',
  `review_remark` varchar(200) NOT NULL DEFAULT '' COMMENT '审批备注（拒绝原因，选填）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_category` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='受限分类访问申请（单分类/全部分类）';

CREATE TABLE `article` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) NOT NULL COMMENT 'URL标识',
  `title` varchar(200) NOT NULL COMMENT '题目',
  `summary` varchar(500) NOT NULL DEFAULT '' COMMENT '摘要',
  `doc_url` varchar(500) NOT NULL DEFAULT '' COMMENT '文档链接',
  `category_id` bigint unsigned NOT NULL COMMENT '所属分类（可为子分类）',
  `difficulty` varchar(10) NOT NULL DEFAULT 'MEDIUM' COMMENT 'EASY/MEDIUM/HARD',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1已发布',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重，越小越靠前',
  `content_md` longtext NOT NULL COMMENT 'Markdown 原文',
  `content_html` longtext NOT NULL COMMENT '渲染并消毒后的 HTML',
  `view_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '浏览量',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人（管理员ID）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_category` (`category_id`,`status`),
  KEY `idx_status` (`status`),
  KEY `idx_difficulty` (`difficulty`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='面试题表';

CREATE TABLE `tag` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '标签名',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='标签表';

CREATE TABLE `article_tag` (
  `article_id` bigint unsigned NOT NULL,
  `tag_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`article_id`,`tag_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目-标签关联';

CREATE TABLE `admin_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` bigint unsigned NOT NULL COMMENT '操作管理员ID',
  `action` varchar(50) NOT NULL COMMENT '动作：USER_DISABLE/ARTICLE_CREATE/ARTICLE_UPDATE...',
  `target_type` varchar(20) NOT NULL COMMENT '对象类型：USER/CATEGORY/ARTICLE/TAG',
  `target_id` bigint unsigned NOT NULL COMMENT '对象ID',
  `detail` varchar(500) NOT NULL DEFAULT '' COMMENT '操作详情',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_admin` (`admin_id`),
  KEY `idx_target` (`target_type`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='管理员操作日志';

-- =====================================================================
-- 种子数据（与开发库一致）
-- =====================================================================


-- 老用户默认拥有全部权限（新注册用户默认 0）
UPDATE `user` SET `full_access` = 1;


-- 受限分类：本人经验、文档链接及其子分类需申请访问
UPDATE `category` SET `access_level` = 'APPLY' WHERE `id` IN (42, 43);






SET FOREIGN_KEY_CHECKS = 1;

